import os

install_script = '#!/bin/bash\n# =========================================================\n# JTG Panel - Automated Installation & Management Script\n# =========================================================\nset -e\n\nRED=\'\\033[0;31m\'\nGREEN=\'\\033[0;32m\'\nYELLOW=\'\\033[1;33m\'\nBLUE=\'\\033[0;34m\'\nCYAN=\'\\033[0;36m\'\nBOLD=\'\\033[1m\'\nNC=\'\\033[0m\'\n\nif [ -f "package.json" ] && grep -q "react-example" "package.json" 2>/dev/null; then\n    WORK_DIR="."\nelif [ -d "Jtg" ]; then\n    WORK_DIR="Jtg"\nelse\n    git clone https://github.com/JishnuTheGamer/Jtg Jtg 2>/dev/null || true\n    WORK_DIR="Jtg"\nfi\ncd "$WORK_DIR" || true\n\nprint_banner() {\n    clear 2>/dev/null || true\n    echo -e "${CYAN}${BOLD}"\n    echo "╔══════════════════════════════════════════════╗"\n    echo "║                                              ║"\n    echo "║     ██╗████████╗ ██████╗                     ║"\n    echo "║     ██║╚══██╔══╝██╔════╝                     ║"\n    echo "║     ██║   ██║   ██║  ███╗                    ║"\n    echo "║     ██║   ██║   ██║   ██║                    ║"\n    echo "║     ██║   ██║   ╚██████╔╝                    ║"\n    echo "║     ╚═╝   ╚═╝    ╚═════╝                     ║"\n    echo "║                                              ║"\n    echo "║              JTG PANEL INSTALLER             ║"\n    echo "║                                              ║"\n    echo "╚══════════════════════════════════════════════╝"\n    echo -e "${NC}"\n}\n\nlog_info() { echo -e "${BLUE}[INFO]${NC} $1"; }\nlog_success() { echo -e "${GREEN}[SUCCESS]${NC} $1"; }\nlog_warning() { echo -e "${YELLOW}[WARNING]${NC} $1"; }\nlog_error() { echo -e "${RED}[ERROR]${NC} $1"; }\n\nrun_pm2() {\n    if command -v pm2 &> /dev/null; then\n        pm2 "$@"\n    elif [ -x "./node_modules/.bin/pm2" ]; then\n        ./node_modules/.bin/pm2 "$@"\n    elif [ -x "/usr/local/bin/pm2" ]; then\n        /usr/local/bin/pm2 "$@"\n    else\n        npx --no-install pm2 "$@" 2>/dev/null || npx pm2 "$@"\n    fi\n}\n\nexecute_step() {\n    local msg="$1"\n    shift\n    local step_id="jtg_step_$RANDOM"\n    local log_file="/tmp/${step_id}.log"\n    rm -f "$log_file"\n    \n    printf "  ${CYAN}→${NC} %-40s " "$msg"\n    \n    # Run command in background and capture all stdout and stderr\n    "$@" > "$log_file" 2>&1 &\n    local pid=$!\n    \n    local spinstr=\'|/-\\\'\n    while kill -0 $pid 2>/dev/null; do\n        local temp=${spinstr#?}\n        printf "[%c]" "$spinstr"\n        local spinstr=$temp${spinstr%"$temp"}\n        sleep 0.08\n        printf "\\b\\b\\b"\n    done\n    \n    wait $pid\n    local status=$?\n    \n    if [ $status -eq 0 ]; then\n        printf "\\r  ${GREEN}✓${NC} %-40s ${GREEN}[Done]${NC}\\n" "$msg"\n    else\n        printf "\\r  ${RED}✗${NC} %-40s ${RED}[Fail]${NC}\\n" "$msg"\n        echo -e "\\n================================================"\n        echo -e "${RED}INSTALLATION STEP FAILED${NC}"\n        echo -e "================================================"\n        echo -e "Step: ${BOLD}$msg${NC}"\n        echo -e "Exit Code: $status"\n        echo -e "\\nOutput / Reason:"\n        if [ -s "$log_file" ]; then\n            tail -n 60 "$log_file"\n        else\n            echo "No output was generated by the command."\n        fi\n        echo -e "================================================"\n        echo -e "Installation stopped safely to prevent invalid states.\\n"\n        exit 1\n    fi\n    return $status\n}\n\ncheck_system_deps() {\n    if ! command -v curl &> /dev/null || ! command -v git &> /dev/null || ! command -v tar &> /dev/null; then\n        if command -v apt-get &> /dev/null; then\n            sudo apt-get update -y -q > /dev/null 2>&1 || true\n            sudo apt-get install -y curl git build-essential ca-certificates tar xz-utils unzip -q > /dev/null 2>&1 || true\n        elif command -v yum &> /dev/null; then\n            sudo yum update -y -q > /dev/null 2>&1 || true\n            sudo yum install -y curl git make gcc-c++ ca-certificates tar xz unzip -q > /dev/null 2>&1 || true\n        fi\n    fi\n    return 0\n}\n\ninstall_docker() {\n    if ! command -v docker &> /dev/null; then\n        curl -fsSL https://get.docker.com | sh > /dev/null 2>&1 || true\n        if command -v systemctl &> /dev/null; then\n            sudo systemctl enable --now docker > /dev/null 2>&1 || true\n        elif command -v service &> /dev/null; then\n            sudo service docker start > /dev/null 2>&1 || true\n        fi\n    fi\n    \n    if ! command -v docker &> /dev/null; then\n        echo "Docker could not be installed automatically. Please install Docker and retry."\n        return 1\n    fi\n    \n    if command -v systemctl &> /dev/null; then\n        sudo systemctl start docker > /dev/null 2>&1 || true\n    fi\n    \n    if ! docker compose version &> /dev/null && ! command -v docker-compose &> /dev/null; then\n        sudo curl -L "https://github.com/docker/compose/releases/download/v2.24.5/docker-compose-$(uname -s)-$(uname -m)" -o /usr/local/bin/docker-compose > /dev/null 2>&1 || true\n        sudo chmod +x /usr/local/bin/docker-compose > /dev/null 2>&1 || true\n    fi\n    \n    if ! docker compose version &> /dev/null && ! command -v docker-compose &> /dev/null; then\n        echo "Docker Compose is required but could not be installed."\n        return 1\n    fi\n    return 0\n}\n\ninstall_node() {\n    local NEED_NODE=0\n    if ! command -v node &> /dev/null; then\n        NEED_NODE=1\n    else\n        local NODE_MAJOR=$(node -v | tr -d \'v\' | cut -d\'.\' -f1)\n        if [ -z "$NODE_MAJOR" ] || [ "$NODE_MAJOR" -lt 20 ]; then\n            NEED_NODE=1\n        fi\n    fi\n\n    if [ "$NEED_NODE" -eq 1 ]; then\n        if command -v apt-get &> /dev/null; then\n            curl -fsSL https://deb.nodesource.com/setup_22.x | sudo -E bash - > /dev/null 2>&1 || true\n            sudo apt-get install -y nodejs > /dev/null 2>&1 || true\n        fi\n        \n        local CURRENT_MAJOR=0\n        if command -v node &> /dev/null; then\n            CURRENT_MAJOR=$(node -v | tr -d \'v\' | cut -d\'.\' -f1)\n        fi\n        \n        if [ "$CURRENT_MAJOR" -lt 20 ]; then\n            local ARCH=$(uname -m)\n            local NODE_ARCH="x64"\n            case "$ARCH" in\n                x86_64) NODE_ARCH="x64" ;;\n                aarch64|arm64) NODE_ARCH="arm64" ;;\n                armv7l) NODE_ARCH="armv7l" ;;\n                *) NODE_ARCH="x64" ;;\n            esac\n            local NODE_DIST="node-v22.13.1-linux-${NODE_ARCH}"\n            curl -fsSL "https://nodejs.org/dist/v22.13.1/${NODE_DIST}.tar.xz" -o /tmp/node22.tar.xz > /dev/null 2>&1 || true\n            if [ -f "/tmp/node22.tar.xz" ]; then\n                sudo tar -xJf /tmp/node22.tar.xz -C /usr/local --strip-components=1 > /dev/null 2>&1 || true\n                rm -f /tmp/node22.tar.xz\n            fi\n        fi\n    fi\n    \n    if ! command -v node &> /dev/null; then\n        echo "Node.js (>=20) installation failed."\n        return 1\n    fi\n    \n    if ! command -v pm2 &> /dev/null; then\n        sudo npm install -g pm2 > /dev/null 2>&1 || true\n    fi\n    return 0\n}\n\nsetup_docker_env() {\n    install_docker\n    if [ ! -f "Dockerfile" ]; then\n        cat << \'EOF2\' > Dockerfile\nFROM node:22-alpine\nRUN apk add --no-cache docker-cli git make g++ python3 curl\nWORKDIR /app\nCOPY package*.json ./\nRUN npm install\nCOPY . .\nRUN npm run build\nEXPOSE 6767\nCMD ["npm", "start"]\nEOF2\n    fi\n    \n    if [ ! -f "docker-compose.yml" ]; then\n        cat << \'EOF2\' > docker-compose.yml\nversion: \'3.8\'\nservices:\n  jtg-main:\n    build: .\n    container_name: jtg-main\n    restart: unless-stopped\n    ports:\n      - "6767:6767"\n    environment:\n      - NODE_ENV=production\n      - PORT=6767\n      - JTG_HOST_DATA_PATH=${PWD}/.data\n    volumes:\n      - ./.data:/app/.data\n      - ./backups:/app/backups\n      - /var/run/docker.sock:/var/run/docker.sock\n\n  jtg-admin:\n    build: .\n    container_name: jtg-admin\n    restart: unless-stopped\n    command: npm run dev\n    ports:\n      - "3000:3000"\n    environment:\n      - NODE_ENV=development\n      - PORT=3000\n      - JTG_HOST_DATA_PATH=${PWD}/.data\n    volumes:\n      - ./.data:/app/.data\n      - ./backups:/app/backups\n      - /var/run/docker.sock:/var/run/docker.sock\nEOF2\n    fi\n}\n\nsetup_node_env() {\n    install_node\n    if [ ! -f "ecosystem.config.cjs" ]; then\n        cat << \'EOF2\' > ecosystem.config.cjs\nmodule.exports = {\n  apps: [\n    {\n      name: "jtg-main",\n      script: "npm",\n      args: "start",\n      instances: 1,\n      autorestart: true,\n      watch: false,\n      max_memory_restart: "1G",\n      env: { NODE_ENV: "production", PORT: 6767 }\n    },\n    {\n      name: "jtg-admin",\n      script: "npm",\n      args: "run dev",\n      instances: 1,\n      autorestart: true,\n      watch: false,\n      max_memory_restart: "2G",\n      env: { NODE_ENV: "development", PORT: 3000 }\n    }\n  ]\n};\nEOF2\n    fi\n}\n\ninstall_dependencies() {\n    if [ -f "package-lock.json" ]; then\n        npm ci || npm install\n    else\n        npm install\n    fi\n}\n\nsetup_owner() {\n    npm run createuser\n}\n\nbuild_application() {\n    npm run build\n}\n\nstart_panel_docker() {\n    local TARGET=$1\n    if command -v docker-compose &> /dev/null; then\n        docker-compose up -d --build "$TARGET"\n    elif command -v docker &> /dev/null && docker compose version &> /dev/null; then\n        docker compose up -d --build "$TARGET"\n    else\n        echo "Docker Compose not found."\n        return 1\n    fi\n    \n    sleep 2\n    local container_status=$(docker inspect --format \'{{.State.Status}}\' "$TARGET" 2>/dev/null || echo "not_found")\n    if [ "$container_status" == "exited" ] || [ "$container_status" == "dead" ] || [ "$container_status" == "not_found" ]; then\n        echo "Docker container $TARGET failed to start. Status: $container_status"\n        echo "--- Docker Logs for $TARGET ---"\n        docker logs "$TARGET" --tail 40 2>&1 || true\n        return 1\n    fi\n    return 0\n}\n\nstart_panel_node() {\n    local TARGET=$1\n    run_pm2 delete "$TARGET" 2>/dev/null || true\n    run_pm2 start ecosystem.config.cjs --only "$TARGET"\n    run_pm2 save --force 2>/dev/null || true\n}\n\nhealth_check() {\n    local PORT=$1\n    local RUNTIME_TYPE=$2\n    local TARGET=$3\n    local ATTEMPTS=0\n    local MAX_ATTEMPTS=30\n\n    while [ $ATTEMPTS -lt $MAX_ATTEMPTS ]; do\n        if curl -s -f "http://127.0.0.1:${PORT}/api/health" >/dev/null 2>&1 || curl -s -f "http://127.0.0.1:${PORT}/" >/dev/null 2>&1; then\n            return 0\n        fi\n        \n        if [ "$RUNTIME_TYPE" == "docker" ]; then\n            local cstatus=$(docker inspect --format \'{{.State.Status}}\' "$TARGET" 2>/dev/null || echo "not_found")\n            if [ "$cstatus" == "exited" ] || [ "$cstatus" == "dead" ]; then\n                echo "Container $TARGET exited unexpectedly during health check."\n                echo "--- Logs for $TARGET ---"\n                docker logs "$TARGET" --tail 50 2>&1 || true\n                return 1\n            fi\n        else\n            if run_pm2 list 2>/dev/null | grep "$TARGET" | grep -qE "errored|stopped"; then\n                echo "PM2 process $TARGET crashed or stopped."\n                echo "--- Logs for $TARGET ---"\n                run_pm2 logs "$TARGET" --lines 40 --nostream 2>&1 || true\n                return 1\n            fi\n        fi\n        \n        sleep 2\n        ATTEMPTS=$((ATTEMPTS + 1))\n    done\n\n    echo "Health check timed out waiting for application on port $PORT."\n    if [ "$RUNTIME_TYPE" == "docker" ]; then\n        echo "--- Container Status ---"\n        docker ps -a --filter "name=$TARGET" || true\n        echo "--- Docker Logs ---"\n        docker logs "$TARGET" --tail 50 2>&1 || true\n    else\n        echo "--- PM2 Status ---"\n        run_pm2 list || true\n        echo "--- PM2 Logs ---"\n        run_pm2 logs "$TARGET" --lines 50 --nostream || true\n    fi\n    return 1\n}\n\ncheck_port() {\n    local PORT=$1\n    if command -v ss &> /dev/null; then\n        if ss -lnt | grep -q ":$PORT "; then return 1; fi\n    elif command -v netstat &> /dev/null; then\n        if netstat -tuln | grep -q ":$PORT "; then return 1; fi\n    elif command -v lsof &> /dev/null; then\n        if lsof -i :$PORT -sTCP:LISTEN -t >/dev/null 2>&1; then return 1; fi\n    fi\n    return 0\n}\n\nshow_status() {\n    local MAIN_STATUS="OFF"\n    local DEV_STATUS="OFF"\n    local SFTP_STATUS="OFF"\n    \n    if (run_pm2 list 2>/dev/null | grep "jtg-main" | grep -q "online") || \\\n       (command -v docker &> /dev/null && docker ps --format \'{{.Names}}\' 2>/dev/null | grep -q "^jtg-main$") || \\\n       curl -s -m 2 http://127.0.0.1:6767/api/health 2>/dev/null | grep -q "JTG Panel"; then\n        MAIN_STATUS="ONLINE"\n    fi\n    \n    if (run_pm2 list 2>/dev/null | grep "jtg-admin" | grep -q "online") || \\\n       (command -v docker &> /dev/null && docker ps --format \'{{.Names}}\' 2>/dev/null | grep -q "^jtg-admin$") || \\\n       curl -s -m 2 http://127.0.0.1:3000/api/health 2>/dev/null | grep -q "JTG Panel"; then\n        DEV_STATUS="ONLINE"\n    fi\n    \n    if [ "$MAIN_STATUS" == "ONLINE" ] || [ "$DEV_STATUS" == "ONLINE" ]; then\n        SFTP_STATUS="ONLINE"\n    fi\n    \n    local IP=$(curl -s -m 2 ifconfig.me 2>/dev/null || curl -s -m 2 icanhazip.com 2>/dev/null || hostname -I 2>/dev/null | awk \'{print $1}\' || echo "localhost")\n\n    echo -e "\\n${CYAN}${BOLD}╔══════════════════════════════════════════════╗"\n    echo -e "║              JTG PANEL STATUS                ║"\n    echo -e "╠══════════════════════════════════════════════╣${NC}"\n    echo -e "║"\n    if [ "$MAIN_STATUS" == "ONLINE" ]; then\n        echo -e "║  Main Panel       : ${GREEN}ONLINE${NC} (http://${IP}:6767)"\n    else\n        echo -e "║  Main Panel       : ${RED}OFF${NC}"\n    fi\n    echo -e "║  Main Port        : 6767"\n    if [ "$DEV_STATUS" == "ONLINE" ]; then\n        echo -e "║  Developer Panel  : ${GREEN}ONLINE${NC} (http://${IP}:3000)"\n    else\n        echo -e "║  Developer Panel  : ${YELLOW}OFF${NC}"\n    fi\n    echo -e "║  Developer Port   : 3000"\n    if [ "$SFTP_STATUS" == "ONLINE" ]; then\n        echo -e "║  SFTP Service     : ${GREEN}ONLINE${NC} (Port 2022)"\n    else\n        echo -e "║  SFTP Service     : ${RED}OFF${NC}"\n    fi\n    echo -e "║"\n    echo -e "${CYAN}${BOLD}╚══════════════════════════════════════════════╝${NC}\\n"\n}\n\ninstall_panel() {\n    local TARGET=$1\n    local PANEL_NAME="Main Panel"\n    local PORT="6767"\n    local SERVICE_NAME="jtg-main"\n    \n    if [ "$TARGET" == "dev" ]; then\n        PANEL_NAME="Developer Panel"\n        PORT="3000"\n        SERVICE_NAME="jtg-admin"\n    fi\n\n    print_banner\n    echo -e "╔══════════════════════════════════════════════╗"\n    echo -e "║          SELECT INSTALLATION MODE            ║"\n    echo -e "╠══════════════════════════════════════════════╣"\n    echo -e "║                                              ║"\n    echo -e "║  1) Docker                                   ║"\n    echo -e "║  2) Local Node.js                            ║"\n    echo -e "║  3) Back                                     ║"\n    echo -e "║                                              ║"\n    echo -e "╚══════════════════════════════════════════════╝"\n    \n    local MODE_CHOICE=""\n    if [ -n "$RUN_CHOICE" ]; then\n        MODE_CHOICE="$RUN_CHOICE"\n    else\n        read -p " Choose an option (1-3): " MODE_CHOICE\n    fi\n\n    if [ "$MODE_CHOICE" == "3" ]; then\n        return\n    fi\n\n    if [ "$MODE_CHOICE" != "1" ] && [ "$MODE_CHOICE" != "2" ]; then\n        log_error "Invalid selection."\n        sleep 1\n        return\n    fi\n    \n    if [ "$TARGET" == "main" ]; then\n        print_banner\n        echo -e "╔══════════════════════════════════════════════╗"\n        echo -e "║              CREATE OWNER ACCOUNT            ║"\n        echo -e "╠══════════════════════════════════════════════╣"\n        \n        local OWNER_USER=""\n        local OWNER_PASS=""\n        local OWNER_PASS2=""\n        \n        if [ -n "$JTG_OWNER_USER" ] && [ -n "$JTG_OWNER_PASS" ]; then\n            OWNER_USER="$JTG_OWNER_USER"\n            OWNER_PASS="$JTG_OWNER_PASS"\n        else\n            while true; do\n                read -p "║ Username: " OWNER_USER\n                if [ -n "$OWNER_USER" ]; then\n                    break\n                fi\n            done\n            \n            while true; do\n                read -s -p "║ Password: " OWNER_PASS\n                echo ""\n                read -s -p "║ Confirm Password: " OWNER_PASS2\n                echo ""\n                if [ "$OWNER_PASS" == "$OWNER_PASS2" ] && [ -n "$OWNER_PASS" ]; then\n                    break\n                else\n                    echo "║ Passwords do not match or are empty. Try again."\n                fi\n            done\n        fi\n        echo -e "╚══════════════════════════════════════════════╝"\n        \n        export JTG_OWNER_USER="$OWNER_USER"\n        export JTG_OWNER_PASS="$OWNER_PASS"\n    fi\n    \n    # Environment Setup\n    mkdir -p .data backups\n    if [ ! -f ".env" ]; then\n        if [ -f ".env.example" ]; then\n            cp .env.example .env\n        else\n            echo "PORT=6767" > .env\n            echo "JWT_SECRET=$(head -c 32 /dev/urandom | base64 2>/dev/null || openssl rand -base64 32)" >> .env\n        fi\n    fi\n\n    print_banner\n    echo -e "╔══════════════════════════════════════════════╗"\n    echo -e "║              INSTALLATION PROGRESS           ║"\n    echo -e "╚══════════════════════════════════════════════╝\\n"\n\n    execute_step "System Requirement Check" check_system_deps\n    \n    if [ "$MODE_CHOICE" == "1" ]; then\n        execute_step "Docker Configuration" setup_docker_env\n        execute_step "Node Environment" install_node\n        execute_step "NPM Dependencies" install_dependencies\n        if [ "$TARGET" == "main" ]; then\n            execute_step "Owner Account Setup" setup_owner\n            execute_step "Building & Starting Docker Container" start_panel_docker jtg-main\n            execute_step "Waiting for Application & Port 6767" health_check 6767 docker jtg-main\n        else\n            execute_step "Building & Starting Docker Container" start_panel_docker jtg-admin\n            execute_step "Waiting for Application & Port 3000" health_check 3000 docker jtg-admin\n        fi\n    else\n        execute_step "Node.js Configuration" setup_node_env\n        execute_step "NPM Dependencies" install_dependencies\n        if [ "$TARGET" == "main" ]; then\n            execute_step "Owner Account Setup" setup_owner\n            execute_step "Building Application" build_application\n            execute_step "Starting PM2 Service" start_panel_node jtg-main\n            execute_step "Waiting for Application & Port 6767" health_check 6767 pm2 jtg-main\n        else\n            execute_step "Building Application" build_application\n            execute_step "Starting PM2 Service" start_panel_node jtg-admin\n            execute_step "Waiting for Application & Port 3000" health_check 3000 pm2 jtg-admin\n        fi\n    fi\n    \n    show_status\n\n    local IP=$(curl -s -m 2 ifconfig.me 2>/dev/null || curl -s -m 2 icanhazip.com 2>/dev/null || hostname -I 2>/dev/null | awk \'{print $1}\' || echo "localhost")\n    if [ "$TARGET" == "main" ]; then\n        log_success "JTG Main Panel installation is complete and verified!"\n        echo -e "${GREEN}✓ You can now open http://${IP}:6767 and log in with \'${OWNER_USER}\'.${NC}\\n"\n    else\n        log_success "JTG Developer Panel installation is complete and verified!"\n        echo -e "${GREEN}✓ Developer Panel running on http://${IP}:3000.${NC}\\n"\n    fi\n}\n\nupdate_panel() {\n    if [ ! -f "update.sh" ]; then\n        log_error "update.sh not found."\n        return\n    fi\n    bash update.sh\n}\n\ncreate_owner_user() {\n    print_banner\n    echo -e "╔══════════════════════════════════════════════╗"\n    echo "║              CREATE OWNER ACCOUNT            ║"\n    echo "╚══════════════════════════════════════════════╝"\n    \n    local OWNER_USER=""\n    local OWNER_PASS=""\n    local OWNER_PASS2=""\n    \n    while true; do\n        read -p "  Username: " OWNER_USER\n        if [ -n "$OWNER_USER" ]; then\n            break\n        fi\n    done\n    \n    while true; do\n        read -s -p "  Password: " OWNER_PASS\n        echo ""\n        read -s -p "  Confirm Password: " OWNER_PASS2\n        echo ""\n        if [ "$OWNER_PASS" == "$OWNER_PASS2" ] && [ -n "$OWNER_PASS" ]; then\n            break\n        else\n            echo "  Passwords do not match or are empty. Try again."\n        fi\n    done\n    \n    export JTG_OWNER_USER="$OWNER_USER"\n    export JTG_OWNER_PASS="$OWNER_PASS"\n    execute_step "Setting up Owner Account" setup_owner\n    log_success "Owner user setup completed successfully!"\n}\n\nuninstall_panel() {\n    if [ ! -f "uninstall.sh" ]; then\n        log_error "uninstall.sh not found."\n        return\n    fi\n    bash uninstall.sh\n}\n\n# Direct invocation support: bash install.sh main / bash install.sh dev\nif [ "$1" == "main" ]; then\n    install_panel "main"\n    exit 0\nelif [ "$1" == "dev" ]; then\n    install_panel "dev"\n    exit 0\nfi\n\nwhile true; do\n    print_banner\n    echo -e "  ${BOLD}1)${NC} Initialize Main Panel"\n    echo -e "  ${BOLD}2)${NC} Initialize Developer Panel"\n    echo -e "  ${BOLD}3)${NC} Update JTG Panel"\n    echo -e "  ${BOLD}4)${NC} Create Owner"\n    echo -e "  ${BOLD}5)${NC} Uninstall JTG Panel"\n    echo -e "  ${BOLD}6)${NC} Exit"\n    echo -e "\\n========================================================"\n    if ! read -p " Choose an option (1-6): " CHOICE; then\n        echo ""\n        break\n    fi\n    case "$CHOICE" in\n        1)\n            install_panel "main"\n            if [ -t 0 ]; then read -p "Press Enter to return to main menu..." || true; fi\n            ;;\n        2)\n            install_panel "dev"\n            if [ -t 0 ]; then read -p "Press Enter to return to main menu..." || true; fi\n            ;;\n        3)\n            update_panel\n            if [ -t 0 ]; then read -p "Press Enter to return to main menu..." || true; fi\n            ;;\n        4)\n            create_owner_user\n            if [ -t 0 ]; then read -p "Press Enter to return to main menu..." || true; fi\n            ;;\n        5)\n            uninstall_panel\n            if [ -t 0 ]; then read -p "Press Enter to return to main menu..." || true; fi\n            ;;\n        6)\n            echo -e "\\n${YELLOW}Exiting script... Goodbye!${NC}\\n"\n            exit 0\n            ;;\n        *)\n            log_error "Invalid option!"\n            sleep 1.5\n            ;;\n    esac\ndone\n'

uninstall_script = '#!/bin/bash\n# =========================================================\n# JTG Panel - Automated Uninstall Script\n# =========================================================\nset -e\n\nRED=\'\\033[0;31m\'\nGREEN=\'\\033[0;32m\'\nCYAN=\'\\033[0;36m\'\nBOLD=\'\\033[1m\'\nNC=\'\\033[0m\'\n\nif [ -f "package.json" ] && grep -q "react-example" "package.json" 2>/dev/null; then\n    WORK_DIR="."\nelif [ -d "Jtg" ]; then\n    WORK_DIR="Jtg"\nelse\n    WORK_DIR="."\nfi\ncd "$WORK_DIR" || true\n\nprint_banner() {\n    clear 2>/dev/null || true\n    echo -e "${CYAN}${BOLD}"\n    echo "╔══════════════════════════════════════════════╗"\n    echo "║             JTG PANEL UNINSTALLER            ║"\n    echo "╠══════════════════════════════════════════════╣"\n    echo -e "${NC}"\n}\n\nlog_info() { echo -e "${CYAN}[INFO]${NC} $1"; }\n\nrun_pm2() {\n    if command -v pm2 &> /dev/null; then\n        pm2 "$@"\n    elif [ -x "./node_modules/.bin/pm2" ]; then\n        ./node_modules/.bin/pm2 "$@"\n    elif [ -x "/usr/local/bin/pm2" ]; then\n        /usr/local/bin/pm2 "$@"\n    else\n        npx --no-install pm2 "$@" 2>/dev/null || npx pm2 "$@"\n    fi\n}\n\nexecute_step() {\n    local msg="$1"\n    shift\n    local step_id="jtg_uninst_$RANDOM"\n    local log_file="/tmp/${step_id}.log"\n    \n    printf "  ${CYAN}→${NC} %-40s " "$msg"\n    "$@" > "$log_file" 2>&1 &\n    local pid=$!\n    \n    local spinstr=\'|/-\\\'\n    while kill -0 $pid 2>/dev/null; do\n        local temp=${spinstr#?}\n        printf "[%c]" "$spinstr"\n        local spinstr=$temp${spinstr%"$temp"}\n        sleep 0.08\n        printf "\\b\\b\\b"\n    done\n    \n    wait $pid\n    local status=$?\n    \n    if [ $status -eq 0 ]; then\n        printf "\\r  ${GREEN}✓${NC} %-40s ${GREEN}[Done]${NC}\\n" "$msg"\n    else\n        printf "\\r  ${RED}✗${NC} %-40s ${RED}[Fail]${NC}\\n" "$msg"\n    fi\n    return $status\n}\n\nprint_banner\necho "║  Select installed runtime:                   ║"\necho "║                                              ║"\necho "║  1) Docker                                   ║"\necho "║  2) Local Node.js                            ║"\necho "║  3) Auto Detect                              ║"\necho "║  4) Back                                     ║"\necho "║                                              ║"\necho "╚══════════════════════════════════════════════╝"\nread -p " Choose an option (1-4): " UN_CHOICE\n\nif [ "$UN_CHOICE" == "4" ]; then\n    exit 0\nfi\n\nRUNTIME="Unknown"\nif [ "$UN_CHOICE" == "1" ]; then RUNTIME="Docker"; fi\nif [ "$UN_CHOICE" == "2" ]; then RUNTIME="Local Node.js"; fi\nif [ "$UN_CHOICE" == "3" ]; then\n    if (run_pm2 list 2>/dev/null | grep -q "jtg-main") || (run_pm2 list 2>/dev/null | grep -q "jtg-admin"); then\n        RUNTIME="Local Node.js"\n    elif command -v docker &> /dev/null && docker ps -a --format \'{{.Names}}\' | grep -qE "^(jtg-main|jtg-admin)$"; then\n        RUNTIME="Docker"\n    else\n        RUNTIME="Local Node.js"\n    fi\nfi\n\nif [ "$RUNTIME" == "Unknown" ]; then\n    echo -e "${RED}[ERROR]${NC} Could not determine runtime. Exiting."\n    sleep 2\n    exit 1\nfi\n\nOWNER="Unknown"\nif [ -f ".data/users.json" ]; then\n    OWNER=$(grep -o \'"username": "[^"]*"\' .data/users.json | head -1 | cut -d\'"\' -f4 || echo "Unknown")\nfi\n\nprint_banner\necho "║ Runtime: $RUNTIME"\necho "║ Panel: JTG Panel"\necho "║ Owner: $OWNER"\necho "║"\necho "║ Are you sure you want to uninstall JTG Panel?║"\necho "║ 1) Yes, continue                             ║"\necho "║ 2) No, cancel                                ║"\necho "╚══════════════════════════════════════════════╝"\nread -p " Choose (1-2): " CONFIRM\n\nif [ "$CONFIRM" != "1" ]; then\n    echo -e "\\nUninstall cancelled."\n    sleep 1\n    exit 0\nfi\n\necho -e "\\n"\n\nstop_docker() {\n    if command -v docker-compose &> /dev/null; then\n        docker-compose down || true\n    elif command -v docker &> /dev/null && docker compose version &> /dev/null; then\n        docker compose down || true\n    fi\n    docker rm -f jtg-main jtg-admin 2>/dev/null || true\n    docker rmi jtg-main jtg-admin 2>/dev/null || true\n}\n\nstop_pm2() {\n    run_pm2 delete jtg-main jtg-admin 2>/dev/null || true\n    run_pm2 save --force 2>/dev/null || true\n}\n\nclean_files() {\n    rm -rf node_modules dist .logs package-lock.json\n}\n\nif [ "$RUNTIME" == "Docker" ]; then\n    execute_step "Stopping Docker Containers" stop_docker\nelse\n    execute_step "Stopping PM2 Services" stop_pm2\nfi\n\nexecute_step "Removing Panel Runtime Files" clean_files\n\necho -e "\\n${CYAN}${BOLD}"\necho "╔══════════════════════════════════════════════╗"\necho "║                                              ║"\necho -e "║            ${GREEN}✓ UNINSTALL COMPLETE${CYAN}              ║"\necho "║                                              ║"\necho "║              JTG PANEL REMOVED               ║"\necho "║                                              ║"\necho "║  Runtime resources cleaned safely.           ║"\necho "║  Unrelated VPS data was preserved.           ║"\necho "║                                              ║"\necho "╚══════════════════════════════════════════════╝"\necho -e "${NC}"\n'

update_script = '#!/bin/bash\nset -e\n\nRED=\'\\033[0;31m\'\nGREEN=\'\\033[0;32m\'\nCYAN=\'\\033[0;36m\'\nYELLOW=\'\\033[1;33m\'\nBOLD=\'\\033[1m\'\nNC=\'\\033[0m\'\n\nprint_banner() {\n    clear 2>/dev/null || true\n    echo -e "${CYAN}${BOLD}"\n    echo "================================================"\n    echo "        JTG PANEL SAFE UPDATE"\n    echo "================================================"\n    echo -e "${NC}"\n}\n\nlog_info() { echo -e "${CYAN}[INFO]${NC} $1"; }\n\nrun_pm2() {\n    if command -v pm2 &> /dev/null; then\n        pm2 "$@"\n    elif [ -x "./node_modules/.bin/pm2" ]; then\n        ./node_modules/.bin/pm2 "$@"\n    elif [ -x "/usr/local/bin/pm2" ]; then\n        /usr/local/bin/pm2 "$@"\n    else\n        npx --no-install pm2 "$@" 2>/dev/null || npx pm2 "$@"\n    fi\n}\n\nexecute_step() {\n    local msg="$1"\n    shift\n    local step_id="jtg_upd_$RANDOM"\n    local log_file="/tmp/${step_id}.log"\n    \n    printf "  ${CYAN}→${NC} %-40s " "$msg"\n    "$@" > "$log_file" 2>&1 &\n    local pid=$!\n    \n    local spinstr=\'|/-\\\'\n    while kill -0 $pid 2>/dev/null; do\n        local temp=${spinstr#?}\n        printf "[%c]" "$spinstr"\n        local spinstr=$temp${spinstr%"$temp"}\n        sleep 0.08\n        printf "\\b\\b\\b"\n    done\n    \n    wait $pid\n    local status=$?\n    if [ $status -eq 0 ]; then\n        printf "\\r  ${GREEN}✓${NC} %-40s ${GREEN}[Done]${NC}\\n" "$msg"\n    else\n        printf "\\r  ${RED}✗${NC} %-40s ${RED}[Fail]${NC}\\n" "$msg"\n        echo -e "\\n${RED}UPDATE FAILED${NC} on step: $msg"\n        if [ -s "$log_file" ]; then\n            tail -n 40 "$log_file"\n        fi\n        return $status\n    fi\n    return $status\n}\n\n# 1. Determine current state\nif [ -f "package.json" ]; then\n    CURRENT_VERSION=$(grep -o \'"version": "[^"]*"\' package.json | head -1 | cut -d\'"\' -f4 || echo "Unknown")\nelse\n    CURRENT_VERSION="Unknown"\nfi\n\nNEW_VERSION="2.0.1"\nif [ -d ".git" ]; then\n    git fetch origin >/dev/null 2>&1 || true\n    NEW_VERSION=$(git show origin/main:package.json 2>/dev/null | grep -o \'"version": "[^"]*"\' | head -1 | cut -d\'"\' -f4 || echo "$CURRENT_VERSION")\nelse\n    NEW_VERSION="$CURRENT_VERSION"\nfi\n\nRUNTIME="Unknown"\nif (run_pm2 list 2>/dev/null | grep -q "jtg-main"); then\n    RUNTIME="Local Node.js"\nelif command -v docker &> /dev/null && docker ps -a --format \'{{.Names}}\' | grep -qE "^jtg-main$"; then\n    RUNTIME="Docker"\nfi\n\nprint_banner\necho "Current Version : $CURRENT_VERSION"\necho "New Version     : $NEW_VERSION"\necho "Runtime         : $RUNTIME"\necho "Main Port       : 6767"\necho "Developer       : OFF"\necho ""\necho "Backup          : READY"\necho "Database        : PROTECTED"\necho "Server Data     : PROTECTED"\necho ""\n\nif [ -z "$NON_INTERACTIVE" ]; then\n    read -p "Continue update? [Y/N] " CONFIRM\n    if [[ ! "$CONFIRM" =~ ^[Yy]$ ]]; then\n        echo -e "\\n${RED}UPDATE CANCELLED${NC}"\n        exit 0\n    fi\nfi\n\necho ""\n\n# 2. Backup\nBACKUP_DIR=".backup/jtg_backup_$(date +"%Y%m%d_%H%M%S")"\nmkdir -p "$BACKUP_DIR"\n\nbackup_data() {\n    cp -r .data settings.json users.json servers.json .env docker-compose.yml ecosystem.config.cjs "$BACKUP_DIR/" 2>/dev/null || true\n    mkdir -p "$BACKUP_DIR/src_backup"\n    cp -r src/ "$BACKUP_DIR/src_backup/" 2>/dev/null || true\n}\nif ! execute_step "Creating backup" backup_data; then\n    echo -e "\\n${RED}UPDATE CANCELLED${NC} - Backup failed"\n    exit 1\nfi\n\n# 3. Download/Fetch\ndownload_update() {\n    if [ -d ".git" ]; then\n        git stash >/dev/null 2>&1 || true\n        git pull origin main >/dev/null 2>&1 || true\n    else\n        sleep 1\n    fi\n}\nexecute_step "Downloading update" download_update\n\n# 4. Install dependencies safely\ninstall_deps() {\n    if [ -f "package-lock.json" ]; then\n        npm ci || npm install\n    else\n        npm install\n    fi\n}\nif ! execute_step "Installing dependencies" install_deps; then\n    echo -e "\\n${RED}UPDATE FAILED${NC}"\n    echo "ROLLBACK STARTED"\n    cp -r "$BACKUP_DIR/"* . 2>/dev/null || true\n    echo "PREVIOUS VERSION RESTORED"\n    exit 1\nfi\n\n# 5. Build\nif ! execute_step "Building application" npm run build; then\n    echo -e "\\n${RED}UPDATE FAILED${NC}"\n    echo "ROLLBACK STARTED"\n    cp -r "$BACKUP_DIR/"* . 2>/dev/null || true\n    cp -r "$BACKUP_DIR/src_backup/"* src/ 2>/dev/null || true\n    echo "PREVIOUS VERSION RESTORED"\n    exit 1\nfi\n\n# 6. Apply & Restart\nrestart_service() {\n    if [ "$RUNTIME" == "Docker" ]; then\n        if command -v docker-compose &> /dev/null; then\n            docker-compose up -d --build jtg-main\n        elif command -v docker &> /dev/null && docker compose version &> /dev/null; then\n            docker compose up -d --build jtg-main\n        fi\n    elif [ "$RUNTIME" == "Local Node.js" ]; then\n        run_pm2 restart jtg-main\n    fi\n}\nexecute_step "Applying safe update" restart_service\n\n# 7. Health Check\nhealth_check_step() {\n    local ATTEMPTS=0\n    while [ $ATTEMPTS -lt 20 ]; do\n        if curl -s -f "http://127.0.0.1:6767/api/health" >/dev/null 2>&1 || curl -s -f "http://127.0.0.1:6767/" >/dev/null 2>&1; then\n            return 0\n        fi\n        sleep 2\n        ATTEMPTS=$((ATTEMPTS + 1))\n    done\n    return 1\n}\n\nif ! execute_step "Health check" health_check_step; then\n    echo -e "\\n${RED}UPDATE FAILED${NC} - Health check did not pass"\n    echo "ROLLBACK STARTED"\n    cp -r "$BACKUP_DIR/"* . 2>/dev/null || true\n    cp -r "$BACKUP_DIR/src_backup/"* src/ 2>/dev/null || true\n    restart_service\n    echo "PREVIOUS VERSION RESTORED"\n    exit 1\nfi\n\necho -e "\\n${GREEN}[SUCCESS]${NC} JTG Panel updated and verified successfully!"\n'

with open("install.sh", "w") as f:
    f.write(install_script)

with open("uninstall.sh", "w") as f:
    f.write(uninstall_script)

with open("update.sh", "w") as f:
    f.write(update_script)

os.chmod("install.sh", 0o755)
os.chmod("uninstall.sh", 0o755)
os.chmod("update.sh", 0o755)

print("Scripts successfully generated.")
